(* [comment removed for export] *)
Lemma kentry_keep_foot : forall E M M' K,
  kentry_ok SEGS E M K ->
  (forall x : word, match kfoot E K with
                    | Some (s, l) => s <= bv_unsigned x < s + l
                    | None => False end -> M' x = M x) ->
  (forall x : word, M x = None -> M' x = None) ->
